  for(const x of [...variants]){
    if(x.startsWith('ال')&&x.length>3)variants.push(x.slice(2));
    if(x.startsWith('لل')&&x.length>3)variants.push(x.slice(2));
  }
  return variants.some(x=>forms.has(x));
