const LESSON_LOCAL_BATCHES=['private-lessons/la-madrassah/pages-017-020.json'];
async function loadDeckLessons(deckId){
  const owner=cloudUser?.id||'local',collection=state;
  let library=state.lessonLibraries?.[deckId]||null;
  const local=/^(localhost|127\.0\.0\.1|192\.168\.|10\.|172\.(1[6-9]|2\d|3[01])\.)/.test(location.hostname);
  const deck=state.decks.find(d=>d.id===deckId);
  if(local&&/madrassah/i.test(deck?.name||'')){
    let changed=false;
    for(const path of LESSON_LOCAL_BATCHES){
      let batch;
      try{const response=await fetch(path,{cache:'no-store'});if(!response.ok)continue;batch=await response.json()}catch{continue}
      if(state!==collection||(cloudUser?.id||'local')!==owner)return null;
      if(!Array.isArray(batch.sentences)||!batch.sentences.every(s=>typeof s.id==='string'&&typeof s.ar==='string'&&typeof s.fr==='string'&&Number.isInteger(s.page)))continue;
      const merged=new Map((library?.sentences||[]).map(s=>[s.id,s]));
      batch.sentences.forEach(s=>merged.set(s.id,{...s,source:batch.source,translationStatus:batch.translationStatus}));
      const next={source:batch.source,translationStatus:batch.translationStatus,sentences:[...merged.values()]};
      changed=changed||JSON.stringify(next)!==JSON.stringify(library);library=next;
    }
    if(changed){state.lessonLibraries??={};state.lessonLibraries[deckId]=library;save()}
  }
  return library;
}
