  select.onchange=()=>openLessonLibrary(select.value);body.append(select);
  if(!library?.sentences?.length){const p=document.createElement('p');p.textContent='Aucune leçon enregistrée pour ce paquet. Les pages préparées sont reliées au paquet Al-Madrassah depuis le serveur local.';body.append(p);return}
