  const missing=state.cards.filter(c=>c.deckId===deckId&&!library.sentences.some(s=>lessonHasWord(s,lessonForms(cardArabicText(c)))));
  const info=document.createElement('details'),summary=document.createElement('summary');summary.textContent=missing.length+' carte(s) sans correspondance';info.append(summary);
  for(const c of missing){const p=document.createElement('p');p.dir='auto';p.textContent=c.front+' — '+c.back;info.append(p)}
  body.append(info);
  const groups=new Map();
