function drawStats(){const id=$('#statsDeckSelect').value,activeIds=new Set(activeDecks().map(d=>d.id)),rev=state.reviews.filter(r=>id==='all'?activeIds.has(r.deckId):r.deckId===id),cards=state.cards.filter(c=>id==='all'?activeIds.has(c.deckId):c.deckId===id),recent=rev.filter(r=>r.at>now()-30*DAY),correct=recent.filter(r=>r.grade!=='again');$('#statReviews').textContent=fmt(recent.length);$('#statRetention').textContent=recent.length?Math.round(correct.length/recent.length*100)+'%':'—';$('#statStreak').textContent=state.streak+' j';$('#statMature').textContent=cards.filter(c=>c.interval>=21).length;const chart=$('#activityChart');chart.innerHTML='';for(let n=13;n>=0;n--){const d=new Date(today()-n*DAY),key=d.toISOString().slice(0,10),count=rev.filter(r=>new Date(r.at).toISOString().slice(0,10)===key).length,col=document.createElement('div');col.className='chart-col';col.innerHTML=`<i style="height:${Math.min(100,count*12)}%"></i><small>${d.toLocaleDateString('fr-FR',{weekday:'narrow'})}</small>`;chart.append(col)}const groups=[['Nouvelles',cards.filter(c=>status(c)==='new').length,'var(--info)'],['En apprentissage',cards.filter(c=>status(c)==='learn').length,'var(--orange)'],['À réviser',cards.filter(c=>status(c)==='review').length,'var(--green)'],['Planifiées',cards.filter(c=>status(c)==='scheduled').length,'#8f72d8']],root=$('#stateBars');root.innerHTML='';groups.forEach(([l,n,color])=>{root.insertAdjacentHTML('beforeend',`<div class="state-row"><span>${l}</span><div class="state-track"><i style="width:${cards.length?n/cards.length*100:0}%;background:${color}"></i></div><b>${n}</b></div>`)} )}
