async function initializePwaUpdates(){if(!('serviceWorker'in navigator)||location.protocol==='file:')return;let reloading=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(reloading)return;reloading=true;location.reload()});try{const registration=await navigator.serviceWorker.register('./sw.js',{scope:'./'});if(registration.waiting&&navigator.serviceWorker.controller)showUpdateBanner(registration);registration.addEventListener('updatefound',()=>{const worker=registration.installing;if(!worker)return;worker.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller)showUpdateBanner(registration)})});const check=()=>registration.update().catch(()=>{});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')check()});setInterval(check,60*60*1000);check()}catch(error){console.error('[OusBrain PWA]',error)}}
