document.addEventListener('keydown',e=>{if(document.querySelector('.quran-dialog-backdrop,.lesson-dialog')||route!=='review'||e.target.matches('input,textarea,select'))return;if(e.code==='Space'){e.preventDefault();reveal()}const grades={1:'again',2:'hard',3:'good',4:'easy'};if(grades[e.key]&&!$('#answerButtons').classList.contains('hidden'))grade(grades[e.key])});
function applyArabicTypography(root=document){root.querySelectorAll('.card-list-row span,.deck-name,.card-note,.activity-item small').forEach(element=>{const raw=element.textContent||'',display=arabicDisplayText(raw);if(containsArabic(raw)&&(!element.classList.contains('arabic-text')||display!==raw))setScriptContent(element,raw)})}
new MutationObserver(records=>{records.forEach(record=>record.addedNodes.forEach(node=>{if(node.nodeType===1)applyArabicTypography(node)}))}).observe(document.body,{childList:true,subtree:true});
verifyKfgqpcFont();loadHafsData().catch(error=>console.error('[OusBrain]',error));
route=(location.hash.slice(1)||'home').replace(/[^a-z]/g,'');if(!document.querySelector(`#${route}View`))route='home';bindRoutes();render();applyArabicTypography();initializeCloudAuth();initializePwaUpdates();
